step.response_schema:
class Stakeholder(BaseModel):
  role: str
  roleDescription: str

class StakeholdersContainer(BaseModel):
  stakeholders: list[Stakeholder]

class CriterionWeight(BaseModel):
  criterion: str
  weight: int

class CriteriaWeightsContainer(BaseModel):
  criteriaWeights: list[CriterionWeight]

step.prompt:
Options: {{options}}
Criteria: {{criteria}}
Evaluate how each option supports each criterion (0-100). Do not rename options or criteria.

step.response_schema:
class Score(BaseModel):
  criterion: str
  score: int

class Evaluation(BaseModel):
  option: str
  scores: list[Score]

class EvaluationsContainer(BaseModel):
  evaluations: list[Evaluation]
